WITH flattened AS (SELECT id, service, log_ts, latency_ms, status_code, attr_key, value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) t AS attr_key, value), remaining_keys AS (SELECT service, id FROM flattened INTERSECT SELECT service, id FROM app_logs WHERE level = 'ERROR'), kept_rows AS (SELECT s.* FROM flattened s INNER JOIN remaining_keys k ON s.service = k.service AND s.id = k.id), valid AS (SELECT id, service, log_ts, value, WEEKOFYEAR(log_ts) AS log_ts_weekofyear, CASE WHEN service = 'checkout' THEN 1 ELSE 0 END AS is_checkout FROM kept_rows WHERE status_code >= 263), metrics AS (SELECT *, COUNT(log_ts_weekofyear) OVER (PARTITION BY service ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 900 PRECEDING AND CURRENT ROW) AS log_ts_weekofyear_count_15m, AVG(log_ts_weekofyear) OVER (PARTITION BY service ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 7200 PRECEDING AND CURRENT ROW) AS log_ts_weekofyear_avg_2h, PERCENT_RANK() OVER (PARTITION BY service ORDER BY log_ts_weekofyear DESC NULLS FIRST) AS log_ts_weekofyear_percent_rank FROM valid) SELECT CASE WHEN log_ts_weekofyear >= 62 THEN 'PREMIUM' ELSE 'STANDARD' END AS log_ts_weekofyear_tier, MAX(log_ts_weekofyear_avg_2h) FILTER (WHERE service = 'auth') AS auth_max_log_ts_weekofyear_avg_2h, COUNT(CASE WHEN service = 'search' THEN 1 END) AS search_count, COUNT(*) AS cnt, PERCENTILE_APPROX(log_ts_weekofyear_avg_2h, 0.95) AS log_ts_weekofyear_avg_2h_p95, ROUND(AVG(log_ts_weekofyear_count_15m), 2) AS avg_log_ts_weekofyear_count_15m FROM metrics GROUP BY CASE WHEN log_ts_weekofyear >= 62 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY auth_max_log_ts_weekofyear_avg_2h DESC
